def compute(vars):
    old_hqla = vars["v1"]
    new_hqla = vars["v2"]
    difference = new_hqla - old_hqla
    return {
        "value": difference,
        "trace": {
            "old_hqla": old_hqla,
            "new_hqla": new_hqla,
            "calculation": "v2 - v1",
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
